export default "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"description\" content=\"新生儿喂奶、大小便与异常情况记录，支持云端保存与家庭账号。\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover,user-scalable=no\">\n<meta name=\"theme-color\" content=\"#f6f8fb\">\n<title>新生儿日常记录</title>\n<style>\n:root{\n  --bg:#f6f8fb;--card:#fff;--text:#172033;--muted:#748096;--line:#e8edf4;\n  --primary:#3974f6;--primary-soft:#eef4ff;--danger:#e5484d;--danger-soft:#fff0f0;\n  --warn:#e79b25;--shadow:0 10px 30px rgba(33,51,82,.07);--radius:18px;\n  --safe-bottom:env(safe-area-inset-bottom,0px)\n}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\nbutton,input,textarea{font:inherit} button{cursor:pointer}.hidden{display:none!important}\nbutton{touch-action:manipulation}\n.topbar{position:sticky;top:0;z-index:30;background:rgba(246,248,251,.94);backdrop-filter:blur(14px);border-bottom:1px solid rgba(232,237,244,.88)}\n.topbar-inner{max-width:1120px;margin:auto;padding:11px 16px;display:flex;align-items:center;justify-content:space-between;gap:10px}\n.brand{display:flex;align-items:center;gap:10px;font-size:16px;font-weight:800}.brand-icon{width:36px;height:36px;border-radius:12px;background:var(--primary);color:#fff;display:grid;place-items:center;font-size:18px}.toolbar{display:flex;gap:8px}.icon-btn{border:1px solid var(--line);background:#fff;color:var(--text);border-radius:12px;padding:8px 11px}\n.shell{max-width:1120px;margin:auto;padding:16px 16px calc(100px + var(--safe-bottom))}.hero{display:grid;grid-template-columns:1.25fr .75fr;gap:14px;margin-bottom:14px}.card,.panel{background:var(--card);border:1px solid #edf1f6;border-radius:var(--radius);box-shadow:var(--shadow)}\n.date-card{padding:18px}.date-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.date-title{font-size:25px;line-height:1.1;font-weight:850}.date-sub{font-size:13px;color:var(--muted);margin-top:5px}.date-nav{display:flex;gap:7px}.date-nav button{width:38px;height:38px;border-radius:12px;border:1px solid var(--line);background:#fff;font-weight:700}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:17px}.stat{background:#f8fafc;border-radius:13px;padding:11px}.stat b{font-size:20px;display:block}.stat span{font-size:11px;color:var(--muted);display:block;margin-top:2px}\n.summary-card{padding:18px;display:flex;flex-direction:column;justify-content:center}.summary-label{font-size:12px;color:var(--muted)}.summary-main{font-size:30px;font-weight:850;margin:5px 0}.summary-desc{font-size:13px;line-height:1.65;color:var(--muted)}\n.panel{overflow:hidden}.tabs{display:flex;gap:5px;overflow:auto;scrollbar-width:none;padding:10px;border-bottom:1px solid var(--line)}.tabs::-webkit-scrollbar{display:none}.tab{border:0;background:transparent;color:var(--muted);padding:9px 13px;border-radius:11px;white-space:nowrap}.tab.active{background:var(--primary-soft);color:var(--primary);font-weight:750}\n.records{padding:5px 10px 14px}.swipe-wrap{position:relative;overflow:hidden;border-bottom:1px solid #eef2f6}.swipe-wrap:last-child{border-bottom:0}.swipe-delete{position:absolute;right:0;top:0;bottom:0;width:88px;border:0;background:var(--danger);color:#fff;font-weight:750;display:grid;place-items:center}.record{position:relative;z-index:1;background:#fff;display:grid;grid-template-columns:57px 38px 1fr 22px;gap:8px;align-items:start;padding:14px 4px;transition:transform .2s ease;touch-action:pan-y;will-change:transform}.record.swiping{transition:none}.time{font-weight:780;font-size:14px;font-variant-numeric:tabular-nums;padding-top:4px}.type-icon{width:33px;height:33px;border-radius:10px;display:grid;place-items:center}.type-icon.feed{background:#edf3ff}.type-icon.elimination{background:#fff7df}.type-icon.abnormal{background:#ffeded}.type-icon.other{background:#f1f4f8}.record-title{font-size:14px;font-weight:760}.record-meta{font-size:12px;color:var(--muted);line-height:1.5;margin-top:3px}.record-note{font-size:12px;line-height:1.55;margin-top:5px;color:#4b5565}.chev{color:#a9b1bf;font-size:21px;line-height:28px}.empty{text-align:center;color:var(--muted);padding:48px 16px}.empty-icon{font-size:38px;margin-bottom:8px}.swipe-tip{font-size:11px;color:#98a2b1;text-align:center;padding:4px 0 10px}\n.fab{position:fixed;z-index:35;right:max(17px,calc((100vw - 1120px)/2 + 17px));bottom:calc(17px + var(--safe-bottom));border:0;border-radius:17px;background:var(--primary);color:#fff;padding:14px 18px;font-weight:800;box-shadow:0 14px 28px rgba(57,116,246,.28);display:flex;align-items:center;gap:7px}\n.menu{position:fixed;right:16px;top:62px;z-index:45;width:224px;padding:7px;background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:0 16px 36px rgba(20,35,61,.15)}.menu button{display:block;width:100%;border:0;background:transparent;text-align:left;padding:11px;border-radius:9px}.menu button:active{background:#f3f6fa}.menu-note{font-size:11px;color:var(--muted);padding:7px 11px 5px;line-height:1.45}\n.backdrop{position:fixed;inset:0;z-index:60;background:rgba(22,31,47,.42);display:flex;align-items:flex-end;justify-content:center;padding:16px}.sheet{width:min(680px,100%);max-height:94vh;overflow:auto;background:#fff;border-radius:24px;box-shadow:0 22px 60px rgba(15,23,42,.28)}.sheet-head{position:sticky;top:0;z-index:3;background:#fff;border-bottom:1px solid var(--line);padding:16px 18px 12px;display:flex;align-items:center;justify-content:space-between}.sheet-title{font-size:18px;font-weight:850}.sheet-close{width:34px;height:34px;border:0;border-radius:10px;background:#f2f4f7;font-size:20px}.sheet-body{padding:16px 18px calc(20px + var(--safe-bottom))}.field{margin-bottom:16px}.label{display:block;font-size:13px;font-weight:760;margin-bottom:8px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}.chips{display:flex;flex-wrap:wrap;gap:8px}.chip{border:1px solid var(--line);background:#fff;border-radius:999px;padding:9px 13px;color:#384357}.chip.active{border-color:var(--primary);background:var(--primary-soft);color:var(--primary);font-weight:760}.chip.warn.active{border-color:#efb657;background:#fff8ea;color:#a86400}.chip.danger.active{border-color:#ef8b8e;background:var(--danger-soft);color:#b52e34}\ninput[type=date],input[type=time],input[type=number],input[type=text],textarea{width:100%;border:1px solid var(--line);border-radius:13px;background:#fff;color:var(--text);padding:12px 13px;outline:none}input:focus,textarea:focus{border-color:#91b0fa;box-shadow:0 0 0 3px rgba(57,116,246,.08)}textarea{min-height:85px;resize:vertical}.amount-line{display:grid;grid-template-columns:1fr 88px;gap:8px;align-items:end;margin-top:9px}.unit-box{height:45px;border-radius:13px;background:#f6f8fb;display:grid;place-items:center;color:var(--muted);font-size:13px}.hint{font-size:11px;color:var(--muted);margin-top:6px;line-height:1.5}.sheet-actions{position:sticky;bottom:0;background:#fff;display:flex;gap:9px;padding-top:11px}.btn{border:1px solid var(--line);background:#fff;border-radius:13px;padding:12px 15px;font-weight:760}.btn.primary{flex:1;background:var(--primary);color:#fff;border-color:var(--primary)}.btn.danger{color:var(--danger)}\n.toast{position:fixed;z-index:100;left:50%;bottom:calc(88px + var(--safe-bottom));transform:translateX(-50%);background:#172033;color:#fff;border-radius:999px;padding:10px 14px;font-size:12px;box-shadow:var(--shadow);white-space:nowrap}\n@media (hover:hover) and (pointer:fine){.swipe-wrap:hover .swipe-delete{opacity:1}.swipe-delete{opacity:.78}}\n@media(max-width:760px){.topbar-inner{padding:9px 12px}.shell{padding:12px 11px calc(92px + var(--safe-bottom))}.hero{grid-template-columns:1fr;gap:10px;margin-bottom:10px}.summary-card{display:none}.date-card{padding:15px}.date-title{font-size:21px}.stats{gap:6px}.stat{padding:9px 7px}.stat b{font-size:17px}.stat span{font-size:10px}.tabs{padding:8px}.tab{padding:8px 11px}.records{padding:4px 8px 12px}.record{grid-template-columns:52px 34px 1fr 18px;padding:13px 2px}.backdrop{padding:0}.sheet{width:100%;border-radius:22px 22px 0 0}.grid2{grid-template-columns:1fr}.fab{right:13px;bottom:calc(13px + var(--safe-bottom));padding:14px 17px}.brand{font-size:15px}.swipe-tip{display:block}}\n@media(min-width:761px){.swipe-tip{display:none}}\n\n.auth-screen{position:fixed;inset:0;z-index:200;background:linear-gradient(180deg,#f7f9fc,#eef3fa);display:grid;place-items:center;padding:20px}.auth-card{width:min(390px,100%);background:#fff;border:1px solid #e7ecf3;border-radius:22px;box-shadow:0 18px 48px rgba(30,49,78,.12);padding:24px}.auth-logo{width:52px;height:52px;border-radius:17px;background:var(--primary);display:grid;place-items:center;font-size:25px;margin-bottom:15px}.auth-title{font-size:22px;font-weight:850}.auth-sub{color:var(--muted);font-size:13px;line-height:1.6;margin:6px 0 19px}.auth-card input{margin-bottom:10px}.login-btn{width:100%;border:0;border-radius:13px;padding:13px;background:var(--primary);color:#fff;font-weight:800}.login-btn:disabled,.btn:disabled{opacity:.6;cursor:default}.login-msg{min-height:20px;color:var(--danger);font-size:12px;margin-top:9px}.auth-hint{margin-top:14px;padding:11px 12px;border-radius:12px;background:#f6f8fb;color:var(--muted);font-size:11px;line-height:1.55}.deploy-notice{padding:14px;border:1px solid #f2cf8b;background:#fff9eb;border-radius:13px;color:#775314;font-size:12px;line-height:1.65}.user-badge{border:1px solid var(--line);background:#fff;border-radius:999px;padding:7px 10px;font-size:12px;font-weight:760;max-width:110px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.server-state{font-size:10px;padding:4px 8px;border-radius:999px;background:#eef4ff;color:var(--primary)}.server-state.warn{background:#fff5df;color:#9a6400}.server-state.ok{background:#eef9f0;color:#278343}.menu-user{font-size:12px;font-weight:750;color:var(--text);padding:8px 11px 2px}.menu-sep{height:1px;background:var(--line);margin:5px 4px}.record-user{display:inline-block;margin-left:5px;padding:2px 6px;border-radius:999px;background:#f1f4f8;color:#7b8493;font-size:10px;font-weight:600;vertical-align:1px}.user-list{border:1px solid var(--line);border-radius:14px;overflow:hidden;margin-bottom:18px}.user-row{display:grid;grid-template-columns:38px 1fr auto;align-items:center;gap:9px;padding:11px;border-bottom:1px solid var(--line)}.user-row:last-child{border-bottom:0}.user-avatar{width:34px;height:34px;border-radius:11px;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center;font-weight:800}.user-info{min-width:0}.user-info b,.user-info span{display:block}.user-info b{font-size:13px}.user-info span{font-size:10px;color:var(--muted);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.user-actions{display:flex;gap:5px}.user-actions button{border:0;background:#f3f6fa;padding:7px 8px;border-radius:8px;font-size:10px}.danger-text{color:var(--danger)!important}.user-loading{padding:20px;text-align:center;color:var(--muted);font-size:12px}.section-title{font-size:13px;font-weight:800;margin:2px 0 10px}.select-input{width:100%;border:1px solid var(--line);border-radius:13px;background:#fff;padding:12px 13px;color:var(--text)}.app-locked{visibility:hidden}@media(max-width:760px){.server-state{display:none}.user-row{grid-template-columns:34px 1fr}.user-actions{grid-column:2;justify-content:flex-start}.auth-card{padding:21px}}\n</style>\n<style>\n.settings-section{border:1px solid var(--line);border-radius:15px;padding:15px;margin-bottom:14px}\n.settings-section-title{font-size:14px;font-weight:850;margin-bottom:12px}\n.settings-desc{font-size:11px;color:var(--muted);line-height:1.55;margin:-5px 0 12px}\n.settings-actions{display:flex;flex-wrap:wrap;gap:8px}.settings-actions .btn{flex:1;min-width:150px}\n.settings-sheet{width:min(760px,100%)}.baby-day{color:var(--primary);font-weight:700}\n.last-record-hint{display:flex;align-items:center;justify-content:space-between;gap:10px;background:#f6f8fb;border-radius:12px;padding:9px 11px;margin:-3px 0 14px;font-size:11px;color:var(--muted)}\n.last-record-hint.warn{background:#fff8ea;color:#9a6400}.text-btn{border:0;background:transparent;color:var(--primary);padding:3px;font-size:11px;white-space:nowrap}\n.chip{position:relative}.chip-badge{display:inline-block;margin-left:4px;padding:1px 4px;border-radius:5px;background:#e7efff;color:#3268d8;font-size:9px;line-height:1.5;vertical-align:1px}\n.chip-badge.last{background:#eaf7ec;color:#278343}.reference-note{font-size:11px;color:var(--muted);margin:7px 0 0;line-height:1.5}.reference-note b{color:var(--primary)}\n.check-row{display:flex;align-items:center;gap:9px;font-size:13px;font-weight:700}.check-row input{width:18px;height:18px;accent-color:var(--primary)}\n</style>\n</head>\n<body>\n<div id=\"authScreen\" class=\"auth-screen\">\n  <div class=\"auth-card\">\n    <div class=\"auth-logo\">👶</div>\n    <div id=\"loginAppTitle\" class=\"auth-title\">新生儿日常记录</div>\n    <div class=\"auth-sub\">家庭共享记录 · 登录后同步喂奶、大小便和异常情况</div>\n    <form id=\"loginForm\">\n      <input id=\"loginUser\" type=\"text\" autocomplete=\"username\" placeholder=\"用户名\" value=\"admin\" maxlength=\"32\">\n      <input id=\"loginPass\" type=\"password\" autocomplete=\"current-password\" placeholder=\"密码\" maxlength=\"128\">\n      <button id=\"loginBtn\" class=\"login-btn\" type=\"submit\">登录</button>\n      <div id=\"loginMsg\" class=\"login-msg\"></div>\n      <div class=\"auth-hint\">首次登录使用账号 <b>admin</b> 和部署时提供的临时密码。登录后可在“账号设置”中修改密码。</div>\n    </form>\n    <div id=\"deployNotice\" class=\"deploy-notice hidden\">暂时无法连接服务，请稍后刷新重试。未提交的内容不会自动保存。</div>\n  </div>\n</div>\n<header id=\"appHeader\" class=\"topbar app-locked\">\n  <div class=\"topbar-inner\">\n    <div class=\"brand\"><div class=\"brand-icon\">👶</div><span id=\"headerAppTitle\">新生儿日常记录</span></div>\n    <div class=\"toolbar\"><span id=\"serverState\" class=\"server-state\">连接中…</span><span id=\"userBadge\" class=\"user-badge\">未登录</span><button id=\"menuBtn\" class=\"icon-btn\" aria-label=\"更多操作\">⋯</button></div>\n  </div>\n</header>\n<div id=\"menu\" class=\"menu hidden\">\n  <div id=\"menuUser\" class=\"menu-user\">未登录</div>\n  <div class=\"menu-note\">记录保存在云端数据库，家庭账号共享同一份记录。</div>\n  <div class=\"menu-sep\"></div>\n  <button id=\"refreshBtn\">↻ 刷新服务器数据</button>\n  <button id=\"accountSettingsBtn\">🔐 账号设置</button>\n  <button id=\"adminSettingsBtn\" class=\"hidden\">⚙️ 管理设置</button>\n  <div class=\"menu-sep\"></div>\n  <button id=\"logoutBtn\">退出登录</button>\n</div>\n<input id=\"importFile\" class=\"hidden\" type=\"file\" accept=\"application/json,.json\">\n\n<main class=\"shell\">\n  <section class=\"hero\">\n    <div class=\"card date-card\">\n      <div class=\"date-head\">\n        <div><div id=\"dateTitle\" class=\"date-title\"></div><div id=\"dateSub\" class=\"date-sub\"></div></div>\n        <div class=\"date-nav\"><button id=\"prevDay\" aria-label=\"前一天\">‹</button><button id=\"todayBtn\" aria-label=\"今天\">今</button><button id=\"nextDay\" aria-label=\"后一天\">›</button></div>\n      </div>\n      <div class=\"stats\">\n        <div class=\"stat\"><b id=\"feedCount\">0</b><span>喂奶次数</span></div>\n        <div class=\"stat\"><b id=\"feedMl\">0 ml</b><span>全天奶量</span></div>\n        <div class=\"stat\"><b id=\"urineCount\">0</b><span>小便次数</span></div>\n        <div class=\"stat\"><b id=\"stoolCount\">0</b><span>大便次数</span></div>\n      </div>\n    </div>\n    <div class=\"card summary-card\">\n      <div class=\"summary-label\">当日概况</div><div id=\"summaryMain\" class=\"summary-main\">0 条</div><div id=\"summaryDesc\" class=\"summary-desc\"></div>\n    </div>\n  </section>\n\n  <section class=\"panel\">\n    <div id=\"tabs\" class=\"tabs\">\n      <button class=\"tab active\" data-filter=\"all\">全部</button>\n      <button class=\"tab\" data-filter=\"feed\">喂奶</button>\n      <button class=\"tab\" data-filter=\"urine\">小便</button>\n      <button class=\"tab\" data-filter=\"stool\">大便</button>\n      <button class=\"tab\" data-filter=\"abnormal\">异常</button>\n      <button class=\"tab\" data-filter=\"other\">其它</button>\n    </div>\n    <div id=\"records\" class=\"records\"></div>\n    <div class=\"swipe-tip\">提示：记录向左滑动可快速删除，点击记录可编辑</div>\n  </section>\n</main>\n<button id=\"addBtn\" class=\"fab\"><span>＋</span><span>新增记录</span></button>\n\n<div id=\"recordModal\" class=\"backdrop hidden\" role=\"dialog\" aria-modal=\"true\">\n  <div class=\"sheet\" onclick=\"event.stopPropagation()\">\n    <div class=\"sheet-head\"><div id=\"sheetTitle\" class=\"sheet-title\">新增记录</div><button id=\"closeModal\" class=\"sheet-close\" aria-label=\"关闭\">×</button></div>\n    <div class=\"sheet-body\">\n      <div class=\"field\"><span class=\"label\">记录类型</span><div id=\"typeSeg\" class=\"chips\">\n        <button class=\"chip active\" data-value=\"feed\">🍼 喂奶</button><button class=\"chip\" data-value=\"elimination\">💧 大小便</button><button class=\"chip\" data-value=\"abnormal\">⚠️ 异常</button><button class=\"chip\" data-value=\"other\">📝 其它</button>\n      </div></div>\n      <div class=\"grid2\">\n        <div class=\"field\"><label class=\"label\" for=\"recordDate\">日期</label><input id=\"recordDate\" type=\"date\"></div>\n        <div class=\"field\"><label class=\"label\" for=\"recordTime\">时间</label><input id=\"recordTime\" type=\"time\"></div>\n      </div>\n      <div id=\"lastRecordHint\" class=\"last-record-hint hidden\"><span id=\"lastRecordText\"></span><button id=\"resetDefaultsBtn\" class=\"text-btn\" type=\"button\">恢复常用默认值</button></div>\n\n      <div id=\"feedFields\">\n        <div class=\"field\"><span class=\"label\">喂养方式</span><div id=\"feedModeSeg\" class=\"chips\"><button class=\"chip active\" data-value=\"奶粉/瓶喂\">奶粉/瓶喂</button><button class=\"chip\" data-value=\"母乳瓶喂\">母乳瓶喂</button><button class=\"chip\" data-value=\"亲喂\">亲喂</button></div></div>\n        <div class=\"field\" id=\"feedAmountField\"><span class=\"label\">奶量</span><div id=\"amountSeg\" class=\"chips\"></div><div id=\"formulaReferenceNote\" class=\"reference-note hidden\"></div><div class=\"amount-line\"><input id=\"feedAmount\" type=\"number\" min=\"0\" max=\"500\" step=\"5\" value=\"60\" inputmode=\"decimal\"><div class=\"unit-box\">毫升 ml</div></div></div>\n        <div id=\"nurseDurationField\" class=\"field hidden\"><label class=\"label\" for=\"nurseDuration\">亲喂时长（分钟）</label><input id=\"nurseDuration\" type=\"number\" min=\"0\" max=\"180\" step=\"1\" inputmode=\"numeric\" placeholder=\"例如 15\"></div>\n      </div>\n\n      <div id=\"eliminationFields\" class=\"hidden\">\n        <div class=\"field\"><span class=\"label\">小类</span><div id=\"eliminationKindSeg\" class=\"chips\"><button class=\"chip active\" data-value=\"urine\">💧 小便</button><button class=\"chip\" data-value=\"stool\">💩 大便</button><button class=\"chip\" data-value=\"both\">💧💩 大小便同时</button></div></div>\n        <div id=\"urineOptions\" class=\"field\"><span class=\"label\">小便情况</span><div id=\"urineStatusSeg\" class=\"chips\"><button class=\"chip active\" data-value=\"正常\">正常</button><button class=\"chip warn\" data-value=\"偏少\">偏少</button><button class=\"chip warn\" data-value=\"偏黄\">偏黄</button><button class=\"chip danger\" data-value=\"异常\">异常</button></div></div>\n        <div id=\"stoolOptions\" class=\"hidden\">\n          <div class=\"field\"><span class=\"label\">大便颜色</span><div id=\"stoolColorSeg\" class=\"chips\"><button class=\"chip active\" data-value=\"黄色\">黄色</button><button class=\"chip\" data-value=\"黄绿色\">黄绿色</button><button class=\"chip\" data-value=\"绿色\">绿色</button><button class=\"chip danger\" data-value=\"黑色/异常\">黑色/异常</button></div></div>\n          <div class=\"field\"><span class=\"label\">大便性状</span><div id=\"stoolFormSeg\" class=\"chips\"><button class=\"chip active\" data-value=\"正常糊状\">正常糊状</button><button class=\"chip\" data-value=\"偏稀\">偏稀</button><button class=\"chip\" data-value=\"水样\">水样</button><button class=\"chip\" data-value=\"偏干\">偏干</button><button class=\"chip danger\" data-value=\"有血丝/异常\">有血丝/异常</button></div></div>\n        </div>\n      </div>\n\n      <div id=\"abnormalFields\" class=\"hidden\">\n        <div class=\"field\"><span class=\"label\">异常类别</span><div id=\"abnormalTypeSeg\" class=\"chips\"><button class=\"chip active\" data-value=\"吐奶/溢奶\">吐奶/溢奶</button><button class=\"chip\" data-value=\"体温\">体温</button><button class=\"chip\" data-value=\"皮肤/黄疸\">皮肤/黄疸</button><button class=\"chip\" data-value=\"哭闹/精神\">哭闹/精神</button><button class=\"chip\" data-value=\"呼吸\">呼吸</button><button class=\"chip\" data-value=\"其它异常\">其它异常</button></div></div>\n        <div class=\"field\"><span class=\"label\">程度</span><div id=\"severitySeg\" class=\"chips\"><button class=\"chip active\" data-value=\"轻微\">轻微</button><button class=\"chip warn\" data-value=\"需关注\">需关注</button><button class=\"chip danger\" data-value=\"明显异常\">明显异常</button></div></div>\n      </div>\n\n      <div id=\"otherFields\" class=\"hidden\"><div class=\"field\"><label class=\"label\" for=\"otherTitle\">事项</label><input id=\"otherTitle\" type=\"text\" placeholder=\"例如：洗澡、脐带护理、维生素D\"></div></div>\n      <div class=\"field\"><label class=\"label\" for=\"note\">备注 / 异常说明</label><textarea id=\"note\" placeholder=\"可记录吐奶、精神状态、颜色、气味、护理情况等\"></textarea><div class=\"hint\">记录会保存到云端数据库，登录后的手机与电脑共享同一份数据。</div></div>\n      <div class=\"sheet-actions\"><button id=\"deleteBtn\" class=\"btn danger hidden\">删除</button><button id=\"saveBtn\" class=\"btn primary\">保存记录</button></div>\n    </div>\n  </div>\n</div>\n\n<div id=\"settingsModal\" class=\"backdrop hidden\" role=\"dialog\" aria-modal=\"true\">\n  <div class=\"sheet settings-sheet\" onclick=\"event.stopPropagation()\">\n    <div class=\"sheet-head\"><div class=\"sheet-title\">管理设置</div><button id=\"closeSettings\" class=\"sheet-close\" aria-label=\"关闭\">×</button></div>\n    <div class=\"sheet-body\">\n      <form id=\"settingsForm\">\n        <section class=\"settings-section\"><div class=\"settings-section-title\">基本设置</div>\n          <div class=\"grid2\"><div class=\"field\"><label class=\"label\" for=\"settingAppTitle\">应用名称</label><input id=\"settingAppTitle\" type=\"text\" maxlength=\"30\" required></div><div class=\"field\"><label class=\"label\" for=\"settingBabyName\">宝宝昵称</label><input id=\"settingBabyName\" type=\"text\" maxlength=\"20\" placeholder=\"例如：小宝\"></div></div>\n          <div class=\"grid2\"><div class=\"field\"><label class=\"label\" for=\"settingBirthDate\">出生日期</label><input id=\"settingBirthDate\" type=\"date\"></div><div class=\"field\"><label class=\"label\" for=\"settingTimezone\">家庭时区</label><select id=\"settingTimezone\" class=\"select-input\"><option value=\"Asia/Shanghai\">中国标准时间</option><option value=\"Etc/UTC\">UTC</option><option value=\"America/Los_Angeles\">美国太平洋时间</option><option value=\"America/New_York\">美国东部时间</option></select></div></div>\n        </section>\n        <section class=\"settings-section\"><div class=\"settings-section-title\">记录设置</div>\n          <div class=\"grid2\"><div class=\"field\"><label class=\"label\" for=\"settingFeedMode\">默认喂养方式</label><select id=\"settingFeedMode\" class=\"select-input\"><option value=\"奶粉/瓶喂\">奶粉/瓶喂</option><option value=\"母乳瓶喂\">母乳瓶喂</option><option value=\"亲喂\">亲喂</option></select></div><div class=\"field\"><label class=\"label\" for=\"settingQuickAmounts\">快捷奶量（ml）</label><input id=\"settingQuickAmounts\" type=\"text\" inputmode=\"numeric\" placeholder=\"30, 60, 90, 120\"></div></div>\n          <div class=\"settings-desc\">使用逗号分隔，最多 8 个数值，范围 5–500 ml。</div>\n          <div class=\"field\"><label class=\"check-row\"><input id=\"settingInheritLast\" type=\"checkbox\">新增时自动沿用最近一次同类记录</label></div>\n          <div class=\"grid2\">\n            <div class=\"field\"><label class=\"label\" for=\"settingReferenceMode\">瓶喂建议值</label><select id=\"settingReferenceMode\" class=\"select-input\"><option value=\"system\">按宝宝日龄显示通用参考</option><option value=\"custom\">使用家庭自定义范围</option></select></div>\n            <div id=\"customReferenceFields\" class=\"field\"><span class=\"label\">家庭建议范围（ml/次）</span><div class=\"grid2\"><input id=\"settingFormulaMin\" type=\"number\" min=\"5\" max=\"500\" step=\"5\"><input id=\"settingFormulaMax\" type=\"number\" min=\"5\" max=\"500\" step=\"5\"></div></div>\n          </div>\n          <div class=\"settings-desc\">建议值只在奶粉/瓶喂时标记，不会覆盖上次实际奶量。</div>\n        </section>\n        <button id=\"saveSettingsBtn\" class=\"btn primary\" type=\"submit\" style=\"width:100%\">保存设置</button>\n      </form>\n      <section class=\"settings-section\" style=\"margin-top:14px\"><div class=\"settings-section-title\">用户与数据</div><div class=\"settings-actions\"><button id=\"openUsersBtn\" class=\"btn\" type=\"button\">👥 用户管理</button><button id=\"settingsExportBtn\" class=\"btn\" type=\"button\">⬇️ 导出备份</button><button id=\"settingsImportBtn\" class=\"btn\" type=\"button\">⬆️ 导入备份</button></div></section>\n    </div>\n  </div>\n</div>\n\n<div id=\"accountModal\" class=\"backdrop hidden\" role=\"dialog\" aria-modal=\"true\">\n  <div class=\"sheet\" onclick=\"event.stopPropagation()\">\n    <div class=\"sheet-head\"><div class=\"sheet-title\">账号设置</div><button id=\"closeAccount\" class=\"sheet-close\" aria-label=\"关闭\">×</button></div>\n    <div class=\"sheet-body\"><form id=\"passwordForm\">\n      <div class=\"field\"><label class=\"label\" for=\"currentPassword\">当前密码</label><input id=\"currentPassword\" type=\"password\" autocomplete=\"current-password\" maxlength=\"128\" required></div>\n      <div class=\"grid2\"><div class=\"field\"><label class=\"label\" for=\"newOwnPassword\">新密码</label><input id=\"newOwnPassword\" type=\"password\" autocomplete=\"new-password\" minlength=\"6\" maxlength=\"128\" required></div><div class=\"field\"><label class=\"label\" for=\"confirmOwnPassword\">确认新密码</label><input id=\"confirmOwnPassword\" type=\"password\" autocomplete=\"new-password\" minlength=\"6\" maxlength=\"128\" required></div></div>\n      <button id=\"changePasswordBtn\" class=\"btn primary\" type=\"submit\" style=\"width:100%\">修改密码</button>\n    </form></div>\n  </div>\n</div>\n\n<div id=\"userModal\" class=\"backdrop hidden\" role=\"dialog\" aria-modal=\"true\">\n  <div class=\"sheet\" onclick=\"event.stopPropagation()\">\n    <div class=\"sheet-head\"><div class=\"sheet-title\">用户管理</div><button id=\"closeUsers\" class=\"sheet-close\" aria-label=\"关闭\">×</button></div>\n    <div class=\"sheet-body\">\n      <div class=\"section-title\">家庭成员</div>\n      <div id=\"userList\" class=\"user-list\"></div>\n      <div class=\"section-title\">新增用户</div>\n      <form id=\"createUserForm\">\n        <div class=\"grid2\"><div class=\"field\"><label class=\"label\">用户名</label><input id=\"newUsername\" type=\"text\" maxlength=\"32\" placeholder=\"例如 mama\" required></div><div class=\"field\"><label class=\"label\">显示名称</label><input id=\"newDisplayName\" type=\"text\" maxlength=\"30\" placeholder=\"例如 妈妈\" required></div></div>\n        <div class=\"grid2\"><div class=\"field\"><label class=\"label\">初始密码</label><input id=\"newPassword\" type=\"password\" minlength=\"6\" maxlength=\"128\" placeholder=\"至少 6 位\" required></div><div class=\"field\"><label class=\"label\">角色</label><select id=\"newRole\" class=\"select-input\"><option value=\"user\">家庭成员</option><option value=\"admin\">管理员</option></select></div></div>\n        <button id=\"createUserBtn\" class=\"btn primary\" type=\"submit\" style=\"width:100%\">创建用户</button>\n      </form>\n    </div>\n  </div>\n</div>\n<div id=\"toast\" class=\"toast hidden\"></div>\n<script>\n'use strict';\nconst $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];\nconst DEFAULT_SETTINGS={appTitle:'新生儿日常记录',babyName:'',birthDate:'',timezone:'Asia/Shanghai',defaultFeedMode:'奶粉/瓶喂',quickAmounts:[30,60,90,120,150],inheritLastRecord:true,formulaReferenceMode:'system',customFormulaMin:60,customFormulaMax:90};\nconst state={date:'',filter:'all',editingId:null,type:'feed',openSwipe:null,records:[],loadedDate:null,user:null,serverReady:false,settings:{...DEFAULT_SETTINGS},latest:{}};\nfunction zonedParts(d=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:state.settings.timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d);return Object.fromEntries(parts.map(x=>[x.type,x.value]))}\nfunction dateStr(d=new Date()){const p=zonedParts(d);return `${p.year}-${p.month}-${p.day}`}\nfunction nowTime(){const p=zonedParts();return `${p.hour}:${p.minute}`}\nfunction esc(v=''){return String(v).replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[c]))}\nfunction fmtDate(s){const d=new Date(s+'T00:00:00'),wd='日一二三四五六'[d.getDay()];return `${d.getMonth()+1}月${d.getDate()}日 · 星期${wd}`}\nfunction toast(msg){const e=$('#toast');e.textContent=msg;e.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.add('hidden'),1900)}\nfunction uuid(){return crypto?.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`}\nasync function api(path,opt={}){const headers=new Headers(opt.headers||{});if(opt.body&&!(opt.body instanceof FormData)&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');const res=await fetch(path,{...opt,headers,credentials:'same-origin'});let data=null;const ct=res.headers.get('content-type')||'';if(ct.includes('application/json'))data=await res.json().catch(()=>null);if(!res.ok){if(res.status===401&&path!=='/api/auth/login')showLogin();const err=new Error(data?.message||`请求失败 (${res.status})`);err.status=res.status;err.data=data;throw err}return data}\nfunction setBusy(btn,busy,text='处理中…'){if(!btn)return;btn.disabled=busy;if(busy){btn.dataset.oldText=btn.textContent;btn.textContent=text}else if(btn.dataset.oldText){btn.textContent=btn.dataset.oldText;delete btn.dataset.oldText}}\nfunction showLogin(msg=''){state.user=null;$('#authScreen').classList.remove('hidden');$('#appHeader').classList.add('app-locked');$('#addBtn').classList.add('hidden');if(msg)$('#loginMsg').textContent=msg}\nfunction hideLogin(){$('#authScreen').classList.add('hidden');$('#appHeader').classList.remove('app-locked');$('#addBtn').classList.remove('hidden')}\nfunction applyUser(user){state.user=user;$('#userBadge').textContent=user.displayName||user.username;$('#menuUser').textContent=`${user.displayName} · ${user.role==='admin'?'管理员':'家庭成员'}`;$('#adminSettingsBtn').classList.toggle('hidden',user.role!=='admin');hideLogin()}\nfunction ageDays(onDate=dateStr()){if(!state.settings.birthDate)return null;const n=Math.floor((Date.parse(onDate+'T00:00:00Z')-Date.parse(state.settings.birthDate+'T00:00:00Z'))/86400000)+1;return n>0?n:null}\nfunction formulaReference(onDate=$('#recordDate')?.value||dateStr()){if(state.settings.formulaReferenceMode==='custom')return {min:Number(state.settings.customFormulaMin),max:Number(state.settings.customFormulaMax),label:'家庭建议'};const days=ageDays(onDate);if(!days)return null;if(days<=7)return {min:30,max:60,label:'出生首周参考'};if(days<=30)return {min:60,max:120,label:'首月参考'};if(days>=150&&days<=210)return {min:180,max:240,label:'约6月龄参考'};return null}\nfunction renderQuickAmounts(selected=Number($('#feedAmount')?.value||0)){const last=state.latest.feed?.feedMode!=='亲喂'?Number(state.latest.feed?.amount||0):0,mode=value('#feedModeSeg')||state.settings.defaultFeedMode,ref=mode==='奶粉/瓶喂'?formulaReference():null,vals=[...(state.settings.quickAmounts||DEFAULT_SETTINGS.quickAmounts)];if(last&&!vals.includes(last))vals.push(last);if(ref){if(!vals.includes(ref.min))vals.push(ref.min);if(!vals.includes(ref.max))vals.push(ref.max)}vals.sort((a,b)=>a-b);$('#amountSeg').innerHTML=vals.map(v=>{const badges=[];if(v===last)badges.push('<span class=\"chip-badge last\">上次</span>');if(ref&&v>=ref.min&&v<=ref.max)badges.push('<span class=\"chip-badge\">参考</span>');return `<button class=\"chip${v===selected?' active':''}\" data-value=\"${v}\">${v} ml${badges.join('')}</button>`}).join('');const note=$('#formulaReferenceNote');if(ref){note.innerHTML=`${ref.label}：<b>${ref.min}–${ref.max} ml/次</b>，请结合宝宝饥饱信号及医嘱`;note.classList.remove('hidden')}else note.classList.add('hidden')}\nfunction applySettings(settings){state.settings={...DEFAULT_SETTINGS,...settings};document.title=state.settings.appTitle;$('#loginAppTitle').textContent=state.settings.appTitle;$('#headerAppTitle').textContent=state.settings.appTitle;renderQuickAmounts()}\nasync function loadSettings(){const data=await api('/api/settings');applySettings(data.settings);state.date=dateStr()}\nasync function loadLatestRecords(){const data=await api('/api/records/latest');state.latest=data.latest||{}}\nasync function bootstrap(){try{try{applySettings(await api('/api/settings/public'))}catch{}const health=await api('/api/health');state.serverReady=!!health?.ok;$('#serverState').textContent='云端已连接';$('#serverState').className='server-state ok';try{const s=await api('/api/auth/session');applyUser(s.user);await loadSettings();await loadLatestRecords();await loadRecords(state.date,true);render()}catch(e){if(e.status!==401)throw e;showLogin()}}catch(e){state.serverReady=false;showLogin();$('#deployNotice').classList.remove('hidden');$('#serverState').textContent='暂时无法连接';$('#serverState').className='server-state warn'}}\nasync function login(e){e.preventDefault();const btn=$('#loginBtn');setBusy(btn,true,'登录中…');$('#loginMsg').textContent='';try{const data=await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:$('#loginUser').value.trim(),password:$('#loginPass').value})});applyUser(data.user);$('#loginPass').value='';state.loadedDate=null;await loadSettings();await loadLatestRecords();await loadRecords(state.date,true);render()}catch(err){$('#loginMsg').textContent=err.message}finally{setBusy(btn,false)}}\nasync function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}state.records=[];state.loadedDate=null;$('#menu').classList.add('hidden');showLogin('已退出登录')}\nasync function loadRecords(date,force=false){if(!state.user)return[];if(!force&&state.loadedDate===date)return state.records;const data=await api(`/api/records?date=${encodeURIComponent(date)}`);state.records=(data.records||[]).map(legacyToCurrent);state.loadedDate=date;return state.records}\nasync function putRecord(rec){const data=await api('/api/records',{method:'POST',body:JSON.stringify(rec)});return data.record}\nasync function deleteRecord(id){return api(`/api/records/${encodeURIComponent(id)}`,{method:'DELETE'})}\nfunction getAll(){return state.records}\nfunction setActive(seg,val){$$(seg+' .chip').forEach(b=>b.classList.toggle('active',b.dataset.value===String(val)))}\nfunction value(seg){return $(seg+' .chip.active')?.dataset.value||''}\nfunction bindSeg(seg,cb){$(seg).addEventListener('click',e=>{const b=e.target.closest('.chip');if(!b)return;setActive(seg,b.dataset.value);cb?.(b.dataset.value)})}\nfunction setType(type){state.type=type;setActive('#typeSeg',type);['feed','elimination','abnormal','other'].forEach(t=>$(`#${t}Fields`).classList.toggle('hidden',t!==type))}\nfunction setEliminationKind(kind){setActive('#eliminationKindSeg',kind);$('#urineOptions').classList.toggle('hidden',kind==='stool');$('#stoolOptions').classList.toggle('hidden',kind==='urine')}\nfunction toggleFeedMode(){const mode=value('#feedModeSeg');$('#feedAmountField').classList.toggle('hidden',mode==='亲喂');$('#nurseDurationField').classList.toggle('hidden',mode!=='亲喂')}\nfunction legacyToCurrent(r){if(r.type==='urine')return {...r,type:'elimination',eliminationKind:'urine',urineStatus:r.status||'正常'};if(r.type==='stool')return {...r,type:'elimination',eliminationKind:'stool'};return r}\nfunction eliminationNeedsAttention(r){return r&&((r.urineStatus&&r.urineStatus!=='正常')||(r.stoolColor&&r.stoolColor!=='黄色')||(r.stoolForm&&r.stoolForm!=='正常糊状'))}\nfunction showLastHint(r){const box=$('#lastRecordHint');if(!r){box.classList.add('hidden');return}const d=describe(r);$('#lastRecordText').textContent=`已沿用上次记录：${r.date} ${r.time} · ${d.title} ${d.meta}${eliminationNeedsAttention(r)?'，请确认本次状态':''}`;box.classList.toggle('warn',eliminationNeedsAttention(r));box.classList.remove('hidden')}\nfunction applyTypeDefaults(type,useLast=true){const last=useLast&&state.settings.inheritLastRecord?state.latest[type]:null,defaultAmount=state.settings.quickAmounts?.[0]||60;if(type==='feed'){const mode=last?.feedMode||state.settings.defaultFeedMode;setActive('#feedModeSeg',mode);$('#feedAmount').value=last&&last.feedMode!=='亲喂'?last.amount??defaultAmount:defaultAmount;$('#nurseDuration').value=last?.feedMode==='亲喂'?last.duration??'':'';toggleFeedMode();renderQuickAmounts(Number($('#feedAmount').value))}else if(type==='elimination'){const r=last||{};setEliminationKind(r.eliminationKind||'urine');setActive('#urineStatusSeg',r.urineStatus||'正常');setActive('#stoolColorSeg',r.stoolColor||'黄色');setActive('#stoolFormSeg',r.stoolForm||'正常糊状')}showLastHint(last)}\nfunction openModal(raw=null){if(!state.user)return;const r=raw?legacyToCurrent(raw):null,defaultAmount=state.settings.quickAmounts?.[0]||60;state.editingId=r?.id||null;$('#sheetTitle').textContent=r?'编辑记录':'新增记录';$('#deleteBtn').classList.toggle('hidden',!r);$('#recordDate').value=r?.date||state.date;$('#recordTime').value=r?.time||nowTime();$('#note').value=r?.note||'';$('#otherTitle').value=r?.otherTitle||'';setType(r?.type||'feed');if(r){$('#feedAmount').value=r.amount??defaultAmount;$('#nurseDuration').value=r.duration??'';setActive('#feedModeSeg',r.feedMode||state.settings.defaultFeedMode);setEliminationKind(r.eliminationKind||'urine');setActive('#urineStatusSeg',r.urineStatus||r.status||'正常');setActive('#stoolColorSeg',r.stoolColor||'黄色');setActive('#stoolFormSeg',r.stoolForm||'正常糊状');toggleFeedMode();renderQuickAmounts(Number($('#feedAmount').value));showLastHint(null)}else applyTypeDefaults('feed',true);setActive('#abnormalTypeSeg',r?.abnormalType||'吐奶/溢奶');setActive('#severitySeg',r?.severity||'轻微');closeAllSwipes();$('#recordModal').classList.remove('hidden')}\nfunction closeModal(){$('#recordModal').classList.add('hidden');state.editingId=null}\nasync function save(){const rec={id:state.editingId||uuid(),date:$('#recordDate').value,time:$('#recordTime').value,type:state.type,note:$('#note').value.trim()};if(!rec.date||!rec.time){toast('请填写日期和时间');return}if(rec.type==='feed'){rec.feedMode=value('#feedModeSeg');if(rec.feedMode==='亲喂')rec.duration=Number($('#nurseDuration').value||0);else rec.amount=Number($('#feedAmount').value||0)}if(rec.type==='elimination'){rec.eliminationKind=value('#eliminationKindSeg');if(rec.eliminationKind!=='stool')rec.urineStatus=value('#urineStatusSeg');if(rec.eliminationKind!=='urine'){rec.stoolColor=value('#stoolColorSeg');rec.stoolForm=value('#stoolFormSeg')}}if(rec.type==='abnormal'){rec.abnormalType=value('#abnormalTypeSeg');rec.severity=value('#severitySeg')}if(rec.type==='other')rec.otherTitle=$('#otherTitle').value.trim()||'其它记录';const btn=$('#saveBtn');setBusy(btn,true,'保存中…');try{await putRecord(rec);state.date=rec.date;state.loadedDate=null;closeModal();toast('已保存到服务器');await loadLatestRecords();await loadRecords(state.date,true);render()}catch(e){toast(e.message)}finally{setBusy(btn,false)}}\nasync function removeCurrent(){if(!state.editingId||!confirm('确认删除这条记录吗？'))return;try{await deleteRecord(state.editingId);state.loadedDate=null;closeModal();toast('已删除');await loadLatestRecords();await loadRecords(state.date,true);render()}catch(e){toast(e.message)}}\nfunction describe(raw){const r=legacyToCurrent(raw);if(r.type==='feed')return {icon:'🍼',title:r.feedMode||'喂奶',meta:r.feedMode==='亲喂'?(r.duration?`亲喂 ${r.duration} 分钟`:'亲喂'):`${r.amount||0} ml`};if(r.type==='elimination'){const k=r.eliminationKind||'urine';if(k==='urine')return {icon:'💧',title:'小便',meta:r.urineStatus||'正常'};if(k==='stool')return {icon:'💩',title:'大便',meta:[r.stoolColor,r.stoolForm].filter(Boolean).join(' · ')};return {icon:'💧💩',title:'大小便',meta:[`小便 ${r.urineStatus||'正常'}`,r.stoolColor,r.stoolForm].filter(Boolean).join(' · ')}}if(r.type==='abnormal')return {icon:'⚠️',title:r.abnormalType||'异常情况',meta:r.severity||''};return {icon:'📝',title:r.otherTitle||'其它记录',meta:'其它'}}\nfunction recordHTML(raw){const r=legacyToCurrent(raw),d=describe(r),who=r.createdByName?`<span class=\"record-user\">${esc(r.createdByName)}记录</span>`:'';return `<div class=\"swipe-wrap\" data-id=\"${esc(r.id)}\"><button class=\"swipe-delete\" data-delete=\"${esc(r.id)}\">删除</button><div class=\"record\" data-id=\"${esc(r.id)}\"><div class=\"time\">${esc(r.time)}</div><div class=\"type-icon ${esc(r.type)}\">${d.icon}</div><div><div class=\"record-title\">${esc(d.title)} ${who}</div><div class=\"record-meta\">${esc(d.meta)}</div>${r.note?`<div class=\"record-note\">${esc(r.note)}</div>`:''}</div><div class=\"chev\">›</div></div></div>`}\nfunction matchesFilter(raw,f){const r=legacyToCurrent(raw);if(f==='all')return true;if(f==='feed'||f==='abnormal'||f==='other')return r.type===f;if(r.type!=='elimination')return false;const k=r.eliminationKind||'urine';return f==='urine'?(k==='urine'||k==='both'):(k==='stool'||k==='both')}\nfunction render(){const day=getAll().filter(r=>r.date===state.date).sort((a,b)=>b.time.localeCompare(a.time)),visible=day.filter(r=>matchesFilter(r,state.filter));$('#dateTitle').textContent=fmtDate(state.date);const age=state.settings.birthDate?Math.floor((Date.parse(state.date+'T00:00:00Z')-Date.parse(state.settings.birthDate+'T00:00:00Z'))/86400000)+1:null,baby=state.settings.babyName?state.settings.babyName+' · ':'',ageText=age&&age>0?`出生第 ${age} 天 · `:'';$('#dateSub').innerHTML=state.date===dateStr()?`${esc(baby)}<span class=\"baby-day\">${esc(ageText)}</span>今天 · 云端同步`:`${esc(baby)}${age&&age>0?`出生第 ${age} 天 · `:''}历史记录 · 云端同步`;const feeds=day.filter(r=>r.type==='feed'),elim=day.filter(r=>r.type==='elimination'),urines=elim.filter(r=>['urine','both'].includes(r.eliminationKind||'urine')),stools=elim.filter(r=>['stool','both'].includes(r.eliminationKind||'urine')),ml=feeds.reduce((s,r)=>s+(r.amount||0),0),abn=day.filter(r=>r.type==='abnormal').length;$('#feedCount').textContent=feeds.length;$('#feedMl').textContent=`${ml} ml`;$('#urineCount').textContent=urines.length;$('#stoolCount').textContent=stools.length;$('#summaryMain').textContent=`${day.length} 条`;$('#summaryDesc').textContent=day.length?`喂奶 ${feeds.length} 次 · 小便 ${urines.length} 次 · 大便 ${stools.length} 次${abn?` · 异常 ${abn} 条`:''}`:'暂无记录，点击“新增记录”开始登记。';$('#records').innerHTML=visible.length?visible.map(recordHTML).join(''):`<div class=\"empty\"><div class=\"empty-icon\">🗓️</div><div>当前分类暂无记录</div></div>`;state.openSwipe=null;bindSwipeRows()}\nasync function shiftDay(n){const d=new Date(state.date+'T12:00:00');d.setDate(d.getDate()+n);state.date=dateStr(d);await loadRecords(state.date);render()}\nfunction closeAllSwipes(except=null){$$('.record').forEach(row=>{if(row!==except)row.style.transform='translateX(0px)'});if(!except)state.openSwipe=null}\nfunction bindSwipeRows(){$$('.record').forEach(row=>{let sx=0,sy=0,dx=0,active=false,horizontal=false;const wrap=row.closest('.swipe-wrap');row.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;active=true;horizontal=false;sx=e.clientX;sy=e.clientY;dx=0;row.classList.add('swiping');try{row.setPointerCapture(e.pointerId)}catch{}});row.addEventListener('pointermove',e=>{if(!active)return;const mx=e.clientX-sx,my=e.clientY-sy;if(!horizontal&&Math.abs(mx)>6&&Math.abs(mx)>Math.abs(my)*1.15)horizontal=true;if(!horizontal)return;dx=Math.max(-88,Math.min(0,mx+(state.openSwipe===wrap?-88:0)));row.style.transform=`translateX(${dx}px)`});const end=()=>{if(!active)return;active=false;row.classList.remove('swiping');if(horizontal){const open=dx<-42;closeAllSwipes(open?row:null);row.style.transform=open?'translateX(-88px)':'translateX(0px)';state.openSwipe=open?wrap:null}horizontal=false};row.addEventListener('pointerup',end);row.addEventListener('pointercancel',end)})}\nasync function deleteBySwipe(id){if(!confirm('确认删除这条记录吗？')){closeAllSwipes();return}try{await deleteRecord(id);state.loadedDate=null;toast('已删除');await loadLatestRecords();await loadRecords(state.date,true);render()}catch(e){toast(e.message)}}\nasync function exportData(){try{const obj=await api('/api/records/export'),blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${state.settings.appTitle}-${dateStr()}-备份.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('服务器备份已导出')}catch(e){toast(e.message)}}\nasync function importData(file){try{const obj=JSON.parse(await file.text());if(!Array.isArray(obj.records))throw new Error('文件格式不正确');if(!confirm(`将向服务器导入 ${obj.records.length} 条记录，重复 ID 会覆盖，是否继续？`))return;if(obj.settings){const saved=await api('/api/settings',{method:'PATCH',body:JSON.stringify(obj.settings)});applySettings(saved.settings)}let imported=0;for(let i=0;i<obj.records.length;i+=200){const batch=await api('/api/records/import',{method:'POST',body:JSON.stringify({records:obj.records.slice(i,i+200)})});imported+=batch.imported;}state.date=dateStr();state.loadedDate=null;toast(`已导入 ${imported} 条`);await loadRecords(state.date,true);render()}catch(e){toast('导入失败：'+e.message)}}\nasync function refresh(){try{state.loadedDate=null;await loadLatestRecords();await loadRecords(state.date,true);render();toast('已刷新服务器数据')}catch(e){toast(e.message)}}\nfunction toggleCustomReference(){const custom=$('#settingReferenceMode').value==='custom';$('#customReferenceFields').classList.toggle('hidden',!custom);$('#settingFormulaMin').required=custom;$('#settingFormulaMax').required=custom}\nasync function openSettings(){if(state.user?.role!=='admin')return;$('#menu').classList.add('hidden');$('#settingAppTitle').value=state.settings.appTitle;$('#settingBabyName').value=state.settings.babyName;$('#settingBirthDate').value=state.settings.birthDate;$('#settingTimezone').value=state.settings.timezone;$('#settingFeedMode').value=state.settings.defaultFeedMode;$('#settingQuickAmounts').value=state.settings.quickAmounts.join(', ');$('#settingInheritLast').checked=state.settings.inheritLastRecord;$('#settingReferenceMode').value=state.settings.formulaReferenceMode;$('#settingFormulaMin').value=state.settings.customFormulaMin;$('#settingFormulaMax').value=state.settings.customFormulaMax;toggleCustomReference();$('#settingsModal').classList.remove('hidden')}\nfunction closeSettings(){$('#settingsModal').classList.add('hidden')}\nasync function saveSettings(e){e.preventDefault();const amounts=$('#settingQuickAmounts').value.split(/[,，\\s]+/).filter(Boolean).map(Number),body={appTitle:$('#settingAppTitle').value.trim(),babyName:$('#settingBabyName').value.trim(),birthDate:$('#settingBirthDate').value,timezone:$('#settingTimezone').value,defaultFeedMode:$('#settingFeedMode').value,quickAmounts:amounts,inheritLastRecord:$('#settingInheritLast').checked,formulaReferenceMode:$('#settingReferenceMode').value,customFormulaMin:Number($('#settingFormulaMin').value),customFormulaMax:Number($('#settingFormulaMax').value)},btn=$('#saveSettingsBtn');setBusy(btn,true,'保存中…');try{const data=await api('/api/settings',{method:'PATCH',body:JSON.stringify(body)});applySettings(data.settings);state.date=dateStr();state.loadedDate=null;await loadRecords(state.date,true);render();toast('管理设置已保存')}catch(e){toast(e.message)}finally{setBusy(btn,false)}}\nfunction openAccount(){$('#menu').classList.add('hidden');$('#passwordForm').reset();$('#accountModal').classList.remove('hidden')}\nfunction closeAccount(){$('#accountModal').classList.add('hidden')}\nasync function changeOwnPassword(e){e.preventDefault();const current=$('#currentPassword').value,next=$('#newOwnPassword').value,confirm=$('#confirmOwnPassword').value;if(next!==confirm){toast('两次输入的新密码不一致');return}const btn=$('#changePasswordBtn');setBusy(btn,true,'修改中…');try{await api('/api/profile/password',{method:'PATCH',body:JSON.stringify({currentPassword:current,newPassword:next})});closeAccount();toast('密码已修改')}catch(e){toast(e.message)}finally{setBusy(btn,false)}}\nasync function openUsers(){if(state.user?.role!=='admin')return;$('#menu').classList.add('hidden');closeSettings();$('#userModal').classList.remove('hidden');await renderUsers()}\nfunction closeUsers(){$('#userModal').classList.add('hidden')}\nasync function renderUsers(){const box=$('#userList');box.innerHTML='<div class=\"user-loading\">正在读取用户…</div>';try{const data=await api('/api/users');box.innerHTML=data.users.map(u=>`<div class=\"user-row\" data-user-id=\"${esc(u.id)}\"><div class=\"user-avatar\">${esc((u.displayName||u.username).slice(0,1))}</div><div class=\"user-info\"><b>${esc(u.displayName)}</b><span>@${esc(u.username)} · ${u.role==='admin'?'管理员':'家庭成员'} · ${u.active?'已启用':'已停用'}</span></div><div class=\"user-actions\"><button data-user-action=\"password\">改密码</button>${u.id===state.user.id?'':`<button data-user-action=\"toggle\" class=\"${u.active?'danger-text':''}\">${u.active?'停用':'启用'}</button>`}</div></div>`).join('')||'<div class=\"user-loading\">暂无用户</div>'}catch(e){box.innerHTML=`<div class=\"user-loading\">${esc(e.message)}</div>`}}\nasync function createUser(e){e.preventDefault();const btn=$('#createUserBtn');setBusy(btn,true,'创建中…');try{await api('/api/users',{method:'POST',body:JSON.stringify({username:$('#newUsername').value.trim(),displayName:$('#newDisplayName').value.trim(),password:$('#newPassword').value,role:$('#newRole').value})});$('#newUsername').value='';$('#newDisplayName').value='';$('#newPassword').value='';toast('用户已创建');await renderUsers()}catch(e){toast(e.message)}finally{setBusy(btn,false)}}\nasync function userAction(e){const btn=e.target.closest('[data-user-action]');if(!btn)return;const row=btn.closest('[data-user-id]'),id=row?.dataset.userId;if(!id)return;if(btn.dataset.userAction==='password'){const p=prompt('输入新密码（至少 6 位）');if(!p)return;try{await api(`/api/users/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({password:p})});toast('密码已更新')}catch(e){toast(e.message)}}else{const isDisable=btn.textContent.trim()==='停用';if(isDisable&&!confirm('停用后该用户已有登录会话会立即失效，是否继续？'))return;try{await api(`/api/users/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({active:isDisable?false:true})});toast(isDisable?'用户已停用':'用户已启用');await renderUsers()}catch(e){toast(e.message)}}}\n$('#loginForm').addEventListener('submit',login);$('#addBtn').addEventListener('click',()=>openModal());$('#closeModal').addEventListener('click',closeModal);$('#recordModal').addEventListener('click',closeModal);$('#saveBtn').addEventListener('click',save);$('#deleteBtn').addEventListener('click',removeCurrent);$('#prevDay').addEventListener('click',()=>shiftDay(-1));$('#nextDay').addEventListener('click',()=>shiftDay(1));$('#todayBtn').addEventListener('click',async()=>{state.date=dateStr();await loadRecords(state.date);render()});$('#tabs').addEventListener('click',e=>{const b=e.target.closest('.tab');if(!b)return;$$('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.filter=b.dataset.filter;render()});$('#records').addEventListener('click',e=>{const del=e.target.closest('[data-delete]');if(del){e.stopPropagation();deleteBySwipe(del.dataset.delete);return}const row=e.target.closest('.record');if(!row)return;if(state.openSwipe){closeAllSwipes();return}const rec=state.records.find(x=>x.id===row.dataset.id);if(rec)openModal(rec)});$('#typeSeg').addEventListener('click',e=>{const b=e.target.closest('.chip');if(b){setType(b.dataset.value);if(!state.editingId)applyTypeDefaults(b.dataset.value,true)}});bindSeg('#feedModeSeg',()=>{toggleFeedMode();renderQuickAmounts(Number($('#feedAmount').value))});bindSeg('#amountSeg',v=>$('#feedAmount').value=v);bindSeg('#eliminationKindSeg',setEliminationKind);bindSeg('#urineStatusSeg');bindSeg('#stoolColorSeg');bindSeg('#stoolFormSeg');bindSeg('#abnormalTypeSeg');bindSeg('#severitySeg');$('#feedAmount').addEventListener('input',()=>setActive('#amountSeg',$('#feedAmount').value));$('#recordDate').addEventListener('change',()=>renderQuickAmounts(Number($('#feedAmount').value)));$('#resetDefaultsBtn').addEventListener('click',()=>applyTypeDefaults(state.type,false));$('#menuBtn').addEventListener('click',e=>{e.stopPropagation();$('#menu').classList.toggle('hidden')});document.addEventListener('click',e=>{if(!e.target.closest('#menu')&&!e.target.closest('#menuBtn'))$('#menu').classList.add('hidden');if(!e.target.closest('.swipe-wrap'))closeAllSwipes()});$('#importFile').addEventListener('change',e=>{if(e.target.files?.[0])importData(e.target.files[0]);e.target.value=''});$('#refreshBtn').addEventListener('click',refresh);$('#logoutBtn').addEventListener('click',logout);$('#accountSettingsBtn').addEventListener('click',openAccount);$('#adminSettingsBtn').addEventListener('click',openSettings);$('#closeSettings').addEventListener('click',closeSettings);$('#settingsModal').addEventListener('click',closeSettings);$('#settingsForm').addEventListener('submit',saveSettings);$('#settingReferenceMode').addEventListener('change',toggleCustomReference);$('#openUsersBtn').addEventListener('click',openUsers);$('#settingsExportBtn').addEventListener('click',exportData);$('#settingsImportBtn').addEventListener('click',()=>$('#importFile').click());$('#closeAccount').addEventListener('click',closeAccount);$('#accountModal').addEventListener('click',closeAccount);$('#passwordForm').addEventListener('submit',changeOwnPassword);$('#closeUsers').addEventListener('click',closeUsers);$('#userModal').addEventListener('click',closeUsers);$('#createUserForm').addEventListener('submit',createUser);$('#userList').addEventListener('click',userAction);bootstrap();\n\n</script>\n</body>\n</html>\n";
